#include <vector>
#include <memory>
#include <iostream>

class HeavyData { /* ... */ };

int main() {
    // Value semantics: v1 stores copies of HeavyData
    std::vector<HeavyData> v1;

    // Reference semantics: v2 stores pointers to shared objects
    using Ptr = std::shared_ptr<HeavyData>;
    std::vector<Ptr> v2;

    Ptr data_a = std::make_shared<HeavyData>();

    v2.push_back(data_a); // Container copies the shared_ptr (cheap)
    v2.push_back(data_a); // Both elements refer to the same object

    // The HeavyData object is only destroyed when v2 and data_a are gone.
}
